package de.corporate.lc.user.service;
import de.corporate.lc.user.repository.AppUserRepository;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.*;import org.springframework.stereotype.Service;import java.util.stream.*;
@Service public class AppUserDetailsService implements UserDetailsService {private final AppUserRepository repo;public AppUserDetailsService(AppUserRepository r){repo=r;}@Override public UserDetails loadUserByUsername(String username){var u=repo.findByUsernameIgnoreCase(username).orElseThrow(()->new UsernameNotFoundException("Benutzer nicht gefunden"));var authorities=Stream.concat(Stream.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())),u.effectivePermissions().stream().map(permission->new SimpleGrantedAuthority("PERM_"+permission.name()))).toList();return User.withUsername(u.getUsername()).password(u.getPasswordHash()).authorities(authorities).disabled(!u.isActive()).build();}}
